def base_string_uri(uri: str, host: str=None) ->str:
    if not isinstance(uri, str):
        raise ValueError('uri must be a string')
    if not uri or uri.strip() == '':
        raise ValueError('uri is empty')
    uri = uri.strip()
    parsed = urlparse.urlsplit(uri)
    scheme = parsed.scheme
    if not scheme:
        raise ValueError('uri has no scheme')
    scheme = scheme.lower()
    netloc = parsed.netloc
    if host is not None:
        netloc = host
    netloc_lower = netloc.lower()
    if not netloc_lower or netloc_lower == ':':
        raise ValueError('uri has no host')
    if netloc_lower.startswith('['):
        bracket_end = netloc_lower.find(']')
        if bracket_end == -1:
            raise ValueError('invalid IPv6 address')
        ipv6_host = netloc_lower[:bracket_end + 1]
        rest = netloc_lower[bracket_end + 1:]
        if rest.startswith(':'):
            port_str = rest[1:]
        else:
            port_str = None
        hostname = ipv6_host
    else:
        if ':' in netloc_lower:
            parts = netloc_lower.rsplit(':', 1)
            hostname = parts[0]
            port_str = parts[1]
            if ':' in hostname:
                raise ValueError('invalid netloc: ' + netloc_lower)
        else:
            hostname = netloc_lower
            port_str = None
    if not hostname or hostname == '':
        raise ValueError('uri has no host')
    if port_str is not None and port_str != '':
        port_str_stripped = port_str.strip()
        if port_str_stripped == '' or port_str_stripped != port_str:
            raise ValueError('invalid port: ' + port_str)
        try:
            port_num = int(port_str)
        except ValueError:
            raise ValueError('invalid port: ' + port_str)
        if port_num <= 0 or port_num > 65535:
            raise ValueError('invalid port number: ' + str(port_num))
        if (scheme == 'http' and port_num == 80) or \
           (scheme == 'https' and port_num == 443):
            port_str = None
    elif port_str == '':
        port_str = None
    if port_str is not None and port_str != '':
        netloc_final = hostname + ':' + port_str
    else:
        netloc_final = hostname
    path = parsed.path
    if not path:
        path = '/'
    path = urlparse.quote(urlparse.unquote(path), safe='/-._~!$&\'()*+,;=:@%')
    netloc_final = urlparse.quote(urlparse.unquote(netloc_final), safe='[]:-._~!$&\'()*+,;=@%')
    result = urlparse.urlunsplit((scheme, netloc_final, path, '', ''))
    return result
